if (! is_dir(resource_path('views/mail'))) {
    mkdir(resource_path('views/mail'), 0700, true);
}
file_put_contents(resource_path('views/mail/simple.blade.php'), 'Receipt');
class SimpleMail extends Illuminate\Mail\Mailable
{
    use Illuminate\Bus\Queueable;
    use Illuminate\Queue\SerializesModels;

    public function envelope(): Illuminate\Mail\Mailables\Envelope
    {
        return new Illuminate\Mail\Mailables\Envelope(subject: 'Receipt');
    }

    public function content(): Illuminate\Mail\Mailables\Content
    {
        return new Illuminate\Mail\Mailables\Content(view: 'mail.simple');
    }
}
config(['mail.mailers.transactional' => ['transport' => 'array']]);
Illuminate\Support\Facades\Mail::mailer('transactional')->to('a@example.test')->send(new SimpleMail());
echo app('mail.manager')->mailer('transactional')->getSymfonyTransport()->messages()->count().':'.app('mail.manager')->mailer()->getSymfonyTransport()->messages()->count().':'.config('mail.default');
